const envelope = $json;
if (!envelope || !['event.updated','event.cancelled'].includes(envelope.type) || envelope.version !== 1) throw new Error('Unsupported CrowdRelay event');
const data = envelope.data ?? {};
const event = data.event ?? {};
const previous = data.previous ?? null;
if (!event.slug || !event.title || !event.starts_at) throw new Error('Missing event fields');
const base = ($env.CROWDRELAY_PUBLIC_SITE_URL || 'https://virya.music').replace(/\/$/, '');
const eventUrl = `${base}/pl/live/${encodeURIComponent(event.slug)}/`;
const tz = event.timezone || 'Europe/Warsaw';
const format = value => value ? new Intl.DateTimeFormat('pl-PL', { dateStyle:'full', timeStyle:'short', timeZone:tz }).format(new Date(value)) : '—';
const kind = envelope.type === 'event.cancelled' ? 'ANULOWANY KONCERT' : 'ZMIANA KONCERTU';
const changes = [];
if (previous?.starts_at && previous.starts_at !== event.starts_at) changes.push(`Termin: ${format(previous.starts_at)} → ${format(event.starts_at)}`);
if ((previous?.venue || '') !== (event.venue || '')) changes.push(`Miejsce: ${previous?.venue || '—'} → ${event.venue || '—'}`);
if ((previous?.venue_address || '') !== (event.venue_address || '')) changes.push(`Adres: ${previous?.venue_address || '—'} → ${event.venue_address || '—'}`);
const marker = `CR_EVENT_ID:${envelope.id}`;
const content = [`## ${kind}`, `**${event.title}**`, envelope.type === 'event.cancelled' ? 'Bandsintown usunął lub anulował ten przyszły termin.' : changes.join('\n') || 'Zmieniły się dane wydarzenia.', `Aktualny widok: ${eventUrl}`, marker].join('\n\n').slice(0,2000);
return [{ json: { marker, content, eventUrl } }];

const source = $('Validate and build change report').first().json;
const messages = Array.isArray($json) ? $json : [];
return [{ json: { ...source, alreadySent: messages.some(message => String(message.content || '').includes(source.marker)) } }];
